cpp:`#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <numeric>\nusing namespace std;\nint main(){\n    vector<int> nums = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3};\n    cout << "原始: ";\n    for (int x : nums) cout << x << " ";\n    cout << "\\n";\n    vector<int> sorted_v = nums;\n    sort(sorted_v.begin(), sorted_v.end());\n    cout << "排序: ";\n    for (int x : sorted_v) cout << x << " ";\n    cout << "\\n";\n    int sum = accumulate(nums.begin(), nums.end(), 0);\n    int mx = *max_element(nums.begin(), nums.end());\n    cout << "總和: " << sum << "\\n";\n    cout << "最大: " << mx << "\\n";\n    int cnt5 = count(nums.begin(), nums.end(), 5);\n    cout << "出現 5 的次數: " << cnt5 << "\\n";\n    return 0;\n}`,
c:`#include <stdio.h>\n#include <stdlib.h>\nint cmp(const void* a, const void* b){return *(int*)a - *(int*)b;}\nint main(){\n    int nums[] = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3};\n    int n = 10;\n    printf("原始: ");\n    for (int i = 0; i < n; i++) printf("%d ", nums[i]);\n    printf("\\n");\n    int sorted[10];\n    for (int i = 0; i < n; i++) sorted[i] = nums[i];\n    qsort(sorted, n, sizeof(int), cmp);\n    printf("排序: ");\n    for (int i = 0; i < n; i++) printf("%d ", sorted[i]);\n    printf("\\n");\n    int sum = 0, mx = nums[0];\n    for (int i = 0; i < n; i++) { sum += nums[i]; if (nums[i] > mx) mx = nums[i]; }\n    printf("總和: %d\\n", sum);\n    printf("最大: %d\\n", mx);\n    return 0;\n}`,
java:`import java.util.*;\npublic class Main {\n    public static void main(String[] args) {\n        int[] nums = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3};\n        System.out.println("原始: " + Arrays.toString(nums));\n        int[] sorted = nums.clone();\n        Arrays.sort(sorted);\n        System.out.println("排序: " + Arrays.toString(sorted));\n        int sum = 0, mx = Integer.MIN_VALUE;\n        for (int x : nums) { sum += x; if (x > mx) mx = x; }\n        System.out.println("總和: " + sum);\n        System.out.println("最大: " + mx);\n    }\n}`
