cpp:`#include <iostream>\nusing namespace std;\nbool is_prime(int n){\n    if (n < 2) return false;\n    for (int i = 2; i*i <= n; i++)\n        if (n % i == 0) return false;\n    return true;\n}\nint main(){\n    int count = 0;\n    cout << "50 以下質數: ";\n    for (int x = 2; x < 50; x++)\n        if (is_prime(x)) { cout << x << " "; count++; }\n    cout << "\\n個數: " << count << "\\n";\n    return 0;\n}`,
c:`#include <stdio.h>\nint is_prime(int n){\n    if (n < 2) return 0;\n    for (int i = 2; i*i <= n; i++)\n        if (n % i == 0) return 0;\n    return 1;\n}\nint main(){\n    int count = 0;\n    printf("50 以下質數: ");\n    for (int x = 2; x < 50; x++)\n        if (is_prime(x)) { printf("%d ", x); count++; }\n    printf("\\n個數: %d\\n", count);\n    return 0;\n}`,
java:`public class Main {\n    static boolean isPrime(int n) {\n        if (n < 2) return false;\n        for (int i = 2; i*i <= n; i++)\n            if (n % i == 0) return false;\n        return true;\n    }\n    public static void main(String[] args) {\n        StringBuilder sb = new StringBuilder("50 以下質數: ");\n        int count = 0;\n        for (int x = 2; x < 50; x++)\n            if (isPrime(x)) { sb.append(x).append(' '); count++; }\n        sb.append("\\n個數: ").append(count);\n        System.out.println(sb);\n    }\n}`
