cpp:`#include <iostream>\n#include <map>\n#include <string>\n#include <sstream>\nusing namespace std;\nint main(){\n    string text = "the quick brown fox jumps over the lazy dog the fox";\n    map<string,int> cnt;\n    stringstream ss(text);\n    string w;\n    while (ss >> w) cnt[w]++;\n    cout << "字頻:\\n";\n    for (auto& p : cnt) cout << "  " << p.first << ": " << p.second << "\\n";\n    cout << "不同字數: " << cnt.size() << "\\n";\n    return 0;\n}`,
c:`/* C 沒有原生 dict/set。\n * 此範例用「平行陣列」做簡單計數。 */\n#include <stdio.h>\n#include <string.h>\nint main(){\n    char* words[] = {"the","quick","brown","fox","jumps","over","the","lazy","dog","the","fox"};\n    int n = 11;\n    char keys[20][20] = {0};\n    int vals[20] = {0}, k = 0;\n    for (int i = 0; i < n; i++) {\n        int found = 0;\n        for (int j = 0; j < k; j++)\n            if (strcmp(keys[j], words[i]) == 0) { vals[j]++; found = 1; break; }\n        if (!found) { strcpy(keys[k], words[i]); vals[k] = 1; k++; }\n    }\n    printf("字頻:\\n");\n    for (int i = 0; i < k; i++) printf("  %s: %d\\n", keys[i], vals[i]);\n    printf("不同字數: %d\\n", k);\n    return 0;\n}`,
java:`import java.util.*;\npublic class Main {\n    public static void main(String[] args) {\n        String text = "the quick brown fox jumps over the lazy dog the fox";\n        Map<String,Integer> cnt = new HashMap<>();\n        for (String w : text.split(" "))\n            cnt.merge(w, 1, Integer::sum);\n        System.out.println("字頻: " + cnt);\n        System.out.println("不同字數: " + cnt.size());\n        // Top 3\n        cnt.entrySet().stream()\n            .sorted((a,b) -> b.getValue() - a.getValue())\n            .limit(3)\n            .forEach(e -> System.out.println("  " + e));\n    }\n}`
