cpp:`#include <iostream>\n#include <vector>\nusing namespace std;\nint main(){\n    vector<int> a = {1, 2, 3, 4, 5, 2, 1, 3};\n    int K = 5;\n    vector<int> ps(a.size()+1, 0);\n    for (size_t i = 0; i < a.size(); i++) ps[i+1] = ps[i] + a[i];\n    int cnt = 0;\n    for (size_t i = 0; i < a.size(); i++)\n        for (size_t j = i; j < a.size(); j++)\n            if (ps[j+1] - ps[i] == K) {\n                cout << "  a[" << i << ".." << j << "] sum = " << K << "\\n";\n                cnt++;\n            }\n    cout << "\\n共 " << cnt << " 個子陣列總和為 " << K << "\\n";\n    return 0;\n}`,
c:`#include <stdio.h>\nint main(){\n    int a[] = {1, 2, 3, 4, 5, 2, 1, 3};\n    int n = 8, K = 5;\n    int ps[9] = {0};\n    for (int i = 0; i < n; i++) ps[i+1] = ps[i] + a[i];\n    int cnt = 0;\n    for (int i = 0; i < n; i++)\n        for (int j = i; j < n; j++)\n            if (ps[j+1] - ps[i] == K) {\n                printf("  a[%d..%d] sum = %d\\n", i, j, K);\n                cnt++;\n            }\n    printf("\\n共 %d 個子陣列總和為 %d\\n", cnt, K);\n    return 0;\n}`,
java:`public class Main {\n    public static void main(String[] args) {\n        int[] a = {1, 2, 3, 4, 5, 2, 1, 3};\n        int K = 5;\n        int n = a.length;\n        int[] ps = new int[n+1];\n        for (int i = 0; i < n; i++) ps[i+1] = ps[i] + a[i];\n        int cnt = 0;\n        for (int i = 0; i < n; i++)\n            for (int j = i; j < n; j++)\n                if (ps[j+1] - ps[i] == K) {\n                    System.out.println("  a[" + i + ".." + j + "] sum = " + K);\n                    cnt++;\n                }\n        System.out.println("\\n共 " + cnt + " 個子陣列總和為 " + K);\n    }\n}`
