cpp:`// C++ 沒有 list comprehension，用標準迴圈或 STL algorithm 取代\n#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nbool is_prime(int n){if(n<2)return false;for(int i=2;i*i<=n;i++)if(n%i==0)return false;return true;}\nint main(){\n    cout << "九九乘法表中乘積為質數的位置:\\n";\n    for (int i = 2; i < 10; i++)\n        for (int j = i; j < 10; j++)\n            if (is_prime(i * j))\n                cout << "  " << i << " x " << j << " = " << i*j << "\\n";\n    return 0;\n}`,
c:`/* C 沒有 list comprehension，用標準迴圈取代 */\n#include <stdio.h>\nint is_prime(int n){if(n<2)return 0;for(int i=2;i*i<=n;i++)if(n%i==0)return 0;return 1;}\nint main(){\n    printf("九九乘法表中乘積為質數的位置:\\n");\n    for (int i = 2; i < 10; i++)\n        for (int j = i; j < 10; j++)\n            if (is_prime(i * j))\n                printf("  %d x %d = %d\\n", i, j, i*j);\n    return 0;\n}`,
java:`// Java 沒有 list comprehension，但有 Stream\nimport java.util.stream.*;\npublic class Main {\n    static boolean isPrime(int n) {\n        if (n < 2) return false;\n        for (int i = 2; i*i <= n; i++) if (n % i == 0) return false;\n        return true;\n    }\n    public static void main(String[] args) {\n        System.out.println("九九乘法表中乘積為質數的位置:");\n        IntStream.range(2, 10).forEach(i ->\n            IntStream.range(i, 10).filter(j -> isPrime(i*j))\n                .forEach(j -> System.out.printf("  %d x %d = %d%n", i, j, i*j)));\n    }\n}`
