c:`#include <stdio.h>\n/* 這支程式想算 1+2+...+n 但有 bug */\nint sum_to(int n){\n    int total = 0;\n    for (int i = 0; i < n; i++)  /* bug: 應是 i=1; i<=n */\n        total += i;\n    return total;\n}\nint main(){\n    printf("sum_to(5) = %d\\n", sum_to(5));\n    printf("預期是 15 但實際是 %d\\n", sum_to(5));\n    /* 修正：for (int i = 1; i <= n; i++) total += i; */\n    return 0;\n}`,
java:`public class Main {\n    // 這支程式想算 1+2+...+n 但有 bug\n    static int sumTo(int n) {\n        int total = 0;\n        for (int i = 0; i < n; i++)  // bug: 應是 i=1; i<=n\n            total += i;\n        return total;\n    }\n    public static void main(String[] args) {\n        System.out.println("sumTo(5) = " + sumTo(5));\n        System.out.println("預期是 15 但實際是 " + sumTo(5));\n        // 修正：for (int i = 1; i <= n; i++) total += i;\n    }\n}`
