cpp:`#include <iostream>\n#include <vector>\n#include <queue>\n#include <utility>\nusing namespace std;\nint main(){\n    int n = 4;\n    vector<vector<pair<int,int>>> g(n);\n    auto add=[&](int a,int b,int w){ g[a].push_back({b,w}); g[b].push_back({a,w}); };\n    add(0,1,1); add(0,2,4); add(1,3,1); add(2,3,1);\n    const int INF = 1e9;\n    vector<int> dist(n, INF);\n    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;\n    dist[0] = 0; pq.push({0,0});\n    while(!pq.empty()){\n        auto cur = pq.top(); pq.pop();\n        int d = cur.first, u = cur.second;\n        if(d != dist[u]) continue;\n        for(auto e : g[u]) if(d + e.second < dist[e.first]){\n            dist[e.first] = d + e.second;\n            pq.push({dist[e.first], e.first});\n        }\n    }\n    for(int i=0;i<n;i++) cout << dist[i] << (i+1==n?'\\n':' ');\n    return 0;\n}`,
c:`#include <stdio.h>\n#define INF 1000000000\nint w[4][4], dist[4], used[4];\nvoid add(int a,int b,int c){ w[a][b] = w[b][a] = c; }\nint main(){\n    for(int i=0;i<4;i++) for(int j=0;j<4;j++) w[i][j] = INF;\n    add(0,1,1); add(0,2,4); add(1,3,1); add(2,3,1);\n    for(int i=0;i<4;i++) dist[i] = INF;\n    dist[0] = 0;\n    for(int step=0; step<4; step++){\n        int u = -1;\n        for(int i=0;i<4;i++) if(!used[i] && (u==-1 || dist[i] < dist[u])) u = i;\n        used[u] = 1;\n        for(int v=0; v<4; v++) if(w[u][v] < INF && dist[u] + w[u][v] < dist[v])\n            dist[v] = dist[u] + w[u][v];\n    }\n    for(int i=0;i<4;i++) printf(\"%d%c\", dist[i], i==3?'\\n':' ');\n    return 0;\n}`,
