cpp:`#include <iostream>\n#include <vector>\n#include <array>\n#include <string>\nusing namespace std;\nstruct Node{ array<int,26> next; bool end=false; Node(){ next.fill(-1); } };\nvector<Node> trie(1);\nvoid insertWord(const string& s){\n    int u = 0;\n    for(char ch : s){\n        int c = ch - 'a';\n        if(trie[u].next[c] == -1){ trie[u].next[c] = trie.size(); trie.push_back(Node()); }\n        u = trie[u].next[c];\n    }\n    trie[u].end = true;\n}\nbool startsWith(const string& s){\n    int u = 0;\n    for(char ch : s){\n        int c = ch - 'a';\n        if(trie[u].next[c] == -1) return false;\n        u = trie[u].next[c];\n    }\n    return true;\n}\nint main(){\n    for(string s : {\"app\",\"apple\",\"ape\",\"bat\"}) insertWord(s);\n    cout << (startsWith(\"ap\") ? \"True\" : \"False\") << "\\n";\n    cout << (startsWith(\"ba\") ? \"True\" : \"False\") << "\\n";\n    cout << (startsWith(\"cat\") ? \"True\" : \"False\") << "\\n";\n    return 0;\n}`,
c:`#include <stdio.h>\n#include <string.h>\nint nxt[100][26], nodes = 1;\nvoid init(){ for(int i=0;i<100;i++) for(int j=0;j<26;j++) nxt[i][j] = -1; }\nvoid insertWord(const char* s){\n    int u = 0;\n    for(int i=0;s[i];i++){\n        int c = s[i] - 'a';\n        if(nxt[u][c] == -1) nxt[u][c] = nodes++;\n        u = nxt[u][c];\n    }\n}\nint startsWith(const char* s){\n    int u = 0;\n    for(int i=0;s[i];i++){\n        int c = s[i] - 'a';\n        if(nxt[u][c] == -1) return 0;\n        u = nxt[u][c];\n    }\n    return 1;\n}\nint main(){\n    init();\n    insertWord(\"app\"); insertWord(\"apple\"); insertWord(\"ape\"); insertWord(\"bat\");\n    printf(\"%s\\n\", startsWith(\"ap\") ? \"True\" : \"False\");\n    printf(\"%s\\n\", startsWith(\"ba\") ? \"True\" : \"False\");\n    printf(\"%s\\n\", startsWith(\"cat\") ? \"True\" : \"False\");\n    return 0;\n}`,
java:`import java.util.*;\npublic class Main {\n    static class Node { int[] next = new int[26]; Node(){ Arrays.fill(next, -1); } }\n    static ArrayList<Node> trie = new ArrayList<>();\n    static void insert(String s){\n        int u = 0;\n        for(char ch : s.toCharArray()){\n            int c = ch - 'a';\n            if(trie.get(u).next[c] == -1){ trie.get(u).next[c] = trie.size(); trie.add(new Node()); }\n            u = trie.get(u).next[c];\n        }\n    }\n    static boolean startsWith(String s){\n        int u = 0;\n        for(char ch : s.toCharArray()){\n            int c = ch - 'a';\n            if(trie.get(u).next[c] == -1) return false;\n            u = trie.get(u).next[c];\n        }\n        return true;\n    }\n    public static void main(String[] args){\n        trie.add(new Node());\n        for(String s : new String[]{\"app\",\"apple\",\"ape\",\"bat\"}) insert(s);\n        System.out.println(startsWith(\"ap\") ? \"True\" : \"False\");\n        System.out.println(startsWith(\"ba\") ? \"True\" : \"False\");\n        System.out.println(startsWith(\"cat\") ? \"True\" : \"False\");\n    }\n}`
