cpp:`#include <iostream>\n#include <vector>\n#include <map>\n#include <set>\n#include <queue>\n#include <unordered_map>\n#include <algorithm>\nusing namespace std;\nint main(){\n    // 1) vector 動態陣列\n    vector<int> v = {3, 1, 4, 1, 5, 9, 2, 6};\n    sort(v.begin(), v.end());\n    cout << "vec:";\n    for(int x : v) cout << ' ' << x;\n    cout << "\\n";\n\n    // 2) map 字母統計 (自動排序)\n    map<char,int> cnt;\n    string s; cin >> s;\n    for(char c : s) cnt[c]++;\n    cout << "letter counts:\\n";\n    for(auto& [k,c] : cnt) cout << "  " << k << ": " << c << "\\n";\n\n    // 3) set 去重\n    set<int> uniq(v.begin(), v.end());\n    cout << "unique: " << uniq.size() << "\\n";\n\n    // 4) priority_queue 大根堆\n    priority_queue<int> pq;\n    for(int x : v) pq.push(x);\n    cout << "top3:";\n    for(int i=0;i<3 && !pq.empty();i++){ cout << ' ' << pq.top(); pq.pop(); }\n    cout << "\\n";\n\n    // 5) unordered_map hash O(1)\n    unordered_map<string,int> price = {{\"apple\",10},{\"banana\",5}};\n    cout << "apple=" << price[\"apple\"] << "\\n";\n    return 0;\n}`,
