cpp:`#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\n// 函式模板：對任何可比大小的型別找最大值\ntemplate<typename T>\nT myMax(T a, T b){ return a > b ? a : b; }\n\n// 類別模板：泛型容器\ntemplate<typename T>\nclass Stack {\n    vector<T> data;\npublic:\n    void push(T x){ data.push_back(x); }\n    T pop(){ T x = data.back(); data.pop_back(); return x; }\n    bool empty() const { return data.empty(); }\n    int size() const { return (int)data.size(); }\n};\n\nint main(){\n    // auto 自動推導\n    auto x = myMax(3, 7);             // int\n    auto y = myMax(1.5, 2.7);          // double\n    auto z = myMax(string(\"apple\"), string(\"banana\"));\n    cout << x << ' ' << y << ' ' << z << "\\n";\n\n    // 同一份 Stack 程式可裝任何型別\n    Stack<int> si;\n    si.push(10); si.push(20); si.push(30);\n    cout << \"stack size=\" << si.size() << \" top=\" << si.pop() << \"\\n\";\n\n    Stack<string> ss;\n    ss.push(\"hello\"); ss.push(\"world\");\n    while(!ss.empty()) cout << ss.pop() << ' ';\n    cout << \"\\n\";\n\n    // 結構化綁定 (C++17)\n    pair<int,string> p = {1, \"one\"};\n    auto [k, v] = p;\n    cout << k << \"=\" << v << \"\\n\";\n    return 0;\n}`
