cpp:`#include <iostream>\n#include <vector>\n#include <utility>\n#include <chrono>\nusing namespace std;\nusing namespace chrono;\n\nvector<int> makeBig(int n){\n    vector<int> v(n);\n    for(int i=0;i<n;i++) v[i] = i;\n    return v;   // C++11 起：自動 move，不再深拷貝\n}\n\nint main(){\n    // 1) move 把 lvalue 變 rvalue：偷光內部資源\n    vector<int> v = {1,2,3,4,5};\n    vector<int> w = move(v);\n    cout << \"after move: v.size=\" << v.size() << \" w.size=\" << w.size() << \"\\n\";\n\n    // 2) 函式回傳大物件：靠 move 不會慢\n    auto t1 = high_resolution_clock::now();\n    auto big = makeBig(1000000);\n    auto t2 = high_resolution_clock::now();\n    cout << \"build 1M ints in \" << duration_cast<microseconds>(t2-t1).count() << \" us\\n\";\n    cout << \"big[999999]=\" << big[999999] << \"\\n\";\n\n    // 3) emplace_back vs push_back\n    vector<pair<int,string>> vec;\n    vec.emplace_back(1, \"one\");      // 原地建構\n    vec.push_back({2, \"two\"});       // 建臨時物件再 move\n    for(auto& [k,s] : vec) cout << k << ':' << s << ' ';\n    cout << \"\\n\";\n    return 0;\n}`
