cpp:`#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <numeric>\nusing namespace std;\nint main(){\n    vector<int> v = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5};\n\n    // 1) sort + unique = 去重\n    vector<int> a = v;\n    sort(a.begin(), a.end());\n    a.erase(unique(a.begin(), a.end()), a.end());\n    cout << \"unique:\"; for(int x : a) cout << ' ' << x; cout << \"\\n\";\n\n    // 2) binary_search / lower_bound / upper_bound\n    cout << \"has 5? \" << binary_search(a.begin(), a.end(), 5) << \"\\n\";\n    auto lb = lower_bound(a.begin(), a.end(), 4);\n    cout << \"first >=4 at index \" << (lb - a.begin()) << \"\\n\";\n\n    // 3) min/max/minmax_element\n    auto [mn, mx] = minmax_element(v.begin(), v.end());\n    cout << \"min=\" << *mn << \" max=\" << *mx << \"\\n\";\n\n    // 4) accumulate 總和\n    int sum = accumulate(v.begin(), v.end(), 0);\n    cout << \"sum=\" << sum << \"\\n\";\n\n    // 5) next_permutation 枚舉全排列\n    vector<int> p = {1, 2, 3};\n    int total = 0;\n    do {\n        for(int x : p) cout << x; cout << ' ';\n        ++total;\n    } while(next_permutation(p.begin(), p.end()));\n    cout << \"\\ntotal=\" << total << \"\\n\";\n    return 0;\n}`
