cpp:`#include <iostream>\n#include <string>\n#include <string_view>\n#include <sstream>\n#include <vector>\nusing namespace std;\n\n// 取受字串切片不做複製\nvoid show(string_view sv){\n    cout << \"[\" << sv << \"] len=\" << sv.size() << \"\\n\";\n}\n\nvector<string> split(const string& s, char delim){\n    vector<string> r;\n    stringstream ss(s);\n    string item;\n    while(getline(ss, item, delim)) r.push_back(item);\n    return r;\n}\n\nint main(){\n    string s = \"hello,world,from,cpp\";\n\n    // 1) string 常用操作\n    cout << \"len=\" << s.size() << \"\\n\";\n    cout << \"sub=\" << s.substr(6, 5) << \"\\n\";    // \"world\"\n    cout << \"find=\" << s.find(\"from\") << \"\\n\";\n\n    // 2) string_view 零複製\n    show(s);\n    show(\"literal\");\n    show(string_view(s).substr(0, 5));            // \"hello\"\n\n    // 3) 自刻 split\n    auto parts = split(s, ',');\n    cout << \"parts=\" << parts.size() << \":\";\n    for(auto& p : parts) cout << ' ' << p;\n    cout << \"\\n\";\n\n    // 4) 數字轉換\n    int n = stoi(\"42\");\n    string ns = to_string(n * 2);\n    cout << \"n=\" << n << \" ns=\" << ns << \"\\n\";\n    return 0;\n}`
