cpp:`#include <iostream>\n#include <thread>\n#include <mutex>\n#include <atomic>\n#include <vector>\n#include <future>\nusing namespace std;\n\nmutex mtx;\nint counterMtx = 0;\natomic<int> counterAtom{0};\n\nvoid incMtx(int loops){\n    for(int i=0;i<loops;i++){\n        lock_guard<mutex> lk(mtx);\n        counterMtx++;\n    }\n}\nvoid incAtom(int loops){\n    for(int i=0;i<loops;i++) counterAtom++;\n}\n\nint main(){\n    const int N = 100000, T = 4;\n\n    // 1) mutex 保護\n    vector<thread> ts;\n    for(int i=0;i<T;i++) ts.emplace_back(incMtx, N);\n    for(auto& t : ts) t.join();\n    cout << \"mutex result=\" << counterMtx << \" (expected \" << N*T << \")\\n\";\n\n    // 2) atomic 原子操作\n    ts.clear();\n    for(int i=0;i<T;i++) ts.emplace_back(incAtom, N);\n    for(auto& t : ts) t.join();\n    cout << \"atomic result=\" << counterAtom.load() << \"\\n\";\n\n    // 3) async + future 取回傳值\n    auto fut = async(launch::async, [](int n){\n        long long s = 0;\n        for(int i=1;i<=n;i++) s += i;\n        return s;\n    }, 1000000);\n    cout << \"sum 1..1e6 = \" << fut.get() << \"\\n\";\n    return 0;\n}`
