c:`#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nint main(){\n    int n;\n    scanf(\"%d\", &n);\n\n    // 1) malloc 動態配置陣列\n    int* arr = (int*)malloc(n * sizeof(int));\n    if(!arr){ fprintf(stderr, \"malloc failed\\n\"); return 1; }\n    for(int i=0;i<n;i++) arr[i] = i * i;\n    printf(\"squares:\");\n    for(int i=0;i<n;i++) printf(\" %d\", arr[i]);\n    printf(\"\\n\");\n\n    // 2) realloc 擴大空間\n    arr = (int*)realloc(arr, 2*n * sizeof(int));\n    for(int i=n;i<2*n;i++) arr[i] = -i;\n    printf(\"after realloc(%d):\", 2*n);\n    for(int i=0;i<2*n;i++) printf(\" %d\", arr[i]);\n    printf(\"\\n\");\n\n    // 3) calloc 初始為 0\n    int* zeros = (int*)calloc(5, sizeof(int));\n    printf(\"calloc:\");\n    for(int i=0;i<5;i++) printf(\" %d\", zeros[i]);\n    printf(\"\\n\");\n\n    // 4) 二維動態陣列\n    int rows = 3, cols = 4;\n    int** grid = (int**)malloc(rows * sizeof(int*));\n    for(int i=0;i<rows;i++){\n        grid[i] = (int*)malloc(cols * sizeof(int));\n        for(int j=0;j<cols;j++) grid[i][j] = i*cols + j;\n    }\n    for(int i=0;i<rows;i++){\n        for(int j=0;j<cols;j++) printf(\"%3d \", grid[i][j]);\n        printf(\"\\n\");\n    }\n\n    // 5) 釋放 (避免 leak)\n    for(int i=0;i<rows;i++) free(grid[i]);\n    free(grid); free(arr); free(zeros);\n    return 0;\n}`,
