c:`#include <stdio.h>\n#include <string.h>\n\nstruct Student {\n    char name[20];\n    int score;\n    double gpa;\n};\n\nunion Data {\n    int i;\n    float f;\n    char s[8];\n};\n\nint main(){\n    // 1) struct 宣告與初始化\n    struct Student s1 = {\"Alice\", 95, 4.0};\n    struct Student s2;\n    strcpy(s2.name, \"Bob\");\n    s2.score = 88;\n    s2.gpa = 3.7;\n    printf(\"%s: score=%d gpa=%.2f\\n\", s1.name, s1.score, s1.gpa);\n    printf(\"%s: score=%d gpa=%.2f\\n\", s2.name, s2.score, s2.gpa);\n\n    // 2) struct 陣列\n    struct Student cls[3] = {\n        {\"A\", 80, 3.0}, {\"B\", 90, 3.5}, {\"C\", 70, 2.5}\n    };\n    int total = 0;\n    for(int i=0;i<3;i++) total += cls[i].score;\n    printf(\"avg score=%.2f\\n\", total/3.0);\n\n    // 3) 指向 struct 的指標 (-> 簡寫)\n    struct Student* p = &s1;\n    printf(\"via ptr: %s scored %d\\n\", p->name, p->score);\n\n    // 4) sizeof struct\n    printf(\"sizeof Student = %zu bytes\\n\", sizeof(struct Student));\n\n    // 5) union 共用記憶體\n    union Data d;\n    d.i = 65;\n    printf(\"union as int: %d, as char: %c\\n\", d.i, d.s[0]);\n    return 0;\n}`
