c:`#include <stdio.h>\n#include <string.h>\n#include <stdlib.h>\n\nint main(){\n    char s[100];\n    fgets(s, sizeof(s), stdin);\n    s[strcspn(s, \"\\n\")] = 0;  // 去掉換行\n\n    // 1) 長度 / 複製 / 串接\n    char buf[200];\n    strcpy(buf, s);\n    strcat(buf, \" world\");\n    printf(\"len=%zu, buf=[%s]\\n\", strlen(s), buf);\n\n    // 2) 比較\n    printf(\"strcmp(\\\"abc\\\",\\\"abd\\\")=%d\\n\", strcmp(\"abc\", \"abd\"));\n\n    // 3) 搜尋子字串\n    char* p = strstr(buf, \"world\");\n    if(p) printf(\"\\\"world\\\" found at index %ld\\n\", p - buf);\n\n    // 4) strtok 切割\n    char csv[] = \"one,two,three,four\";\n    char* tok = strtok(csv, \",\");\n    int idx = 0;\n    while(tok){\n        printf(\"  tok[%d]=%s\\n\", idx++, tok);\n        tok = strtok(NULL, \",\");\n    }\n\n    // 5) 字串轉數字\n    int n = atoi(\"42\");\n    double d = atof(\"3.14\");\n    printf(\"n=%d d=%.2f\\n\", n, d);\n\n    // 6) snprintf 安全格式化\n    char out[64];\n    snprintf(out, sizeof(out), \"result=%d/%.2f\", n, d);\n    printf(\"%s\\n\", out);\n    return 0;\n}`,
