87:{
java:`import java.util.*;\npublic class Main {\n    public static void main(String[] args){\n        // 1) ArrayList 動態陣列\n        List<Integer> list = new ArrayList<>(Arrays.asList(3, 1, 4, 1, 5, 9, 2, 6));\n        Collections.sort(list);\n        System.out.println(\"sorted: \" + list);\n\n        // 2) HashMap 字母計數\n        Map<Character, Integer> cnt = new HashMap<>();\n        String s = \"mississippi\";\n        for(char c : s.toCharArray()) cnt.merge(c, 1, Integer::sum);\n        System.out.println(\"counts: \" + new TreeMap<>(cnt));\n\n        // 3) HashSet 去重\n        Set<Integer> uniq = new HashSet<>(list);\n        System.out.println(\"unique: \" + uniq.size());\n\n        // 4) PriorityQueue 最小堆\n        PriorityQueue<Integer> pq = new PriorityQueue<>(list);\n        System.out.print(\"top3 smallest:\");\n        for(int i=0;i<3 && !pq.isEmpty();i++) System.out.print(\" \" + pq.poll());\n        System.out.println();\n\n        // 5) Deque (ArrayDeque 同時當 stack/queue)\n        Deque<Integer> dq = new ArrayDeque<>();\n        dq.push(1); dq.push(2); dq.push(3);\n        System.out.println(\"stack pop: \" + dq.pop());\n        dq.offer(99);\n        System.out.println(\"queue poll: \" + dq.poll());\n\n        // 6) TreeMap 自動排序 key\n        TreeMap<String,Integer> tm = new TreeMap<>();\n        tm.put(\"banana\", 5); tm.put(\"apple\", 10); tm.put(\"cherry\", 3);\n        System.out.println(\"first: \" + tm.firstKey() + \" last: \" + tm.lastKey());\n    }\n}`
},
