java:`import java.util.*;\npublic class Main {\n    // 1) 泛型類別\n    static class Pair<A, B> {\n        A first; B second;\n        Pair(A a, B b){ first = a; second = b; }\n        public String toString(){ return \"(\" + first + \", \" + second + \")\"; }\n    }\n\n    // 2) 泛型方法 + bounded type\n    static <T extends Comparable<T>> T maxOf(List<T> list){\n        T best = list.get(0);\n        for(T x : list) if(x.compareTo(best) > 0) best = x;\n        return best;\n    }\n\n    // 3) 通配符 (wildcard) - 唯讀讀取\n    static double sumOfNumbers(List<? extends Number> list){\n        double s = 0;\n        for(Number n : list) s += n.doubleValue();\n        return s;\n    }\n\n    public static void main(String[] args){\n        Pair<String, Integer> p = new Pair<>(\"age\", 17);\n        System.out.println(p);\n\n        System.out.println(\"max int: \" + maxOf(Arrays.asList(3, 1, 4, 1, 5, 9, 2)));\n        System.out.println(\"max str: \" + maxOf(Arrays.asList(\"apple\", \"banana\", \"cherry\")));\n\n        List<Integer> ints = Arrays.asList(1, 2, 3, 4, 5);\n        List<Double> dbls = Arrays.asList(1.1, 2.2, 3.3);\n        System.out.println(\"sum ints: \" + sumOfNumbers(ints));\n        System.out.println(\"sum dbls: \" + sumOfNumbers(dbls));\n\n        // 4) Type erasure 提醒 (執行期看不見泛型參數)\n        System.out.println(\"same class? \" + (ints.getClass() == dbls.getClass()));\n    }\n}`
