java:`import java.util.*;\nimport java.util.stream.*;\npublic class Main {\n    public static void main(String[] args){\n        List<Integer> nums = Arrays.asList(3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5);\n\n        // 1) filter + map + collect\n        List<Integer> evens = nums.stream()\n            .filter(x -> x % 2 == 0)\n            .map(x -> x * x)\n            .collect(Collectors.toList());\n        System.out.println(\"even squared: \" + evens);\n\n        // 2) reduce 求和\n        int sum = nums.stream().mapToInt(Integer::intValue).sum();\n        int prod = nums.stream().reduce(1, (a,b) -> a*b);\n        System.out.println(\"sum=\" + sum + \" prod=\" + prod);\n\n        // 3) Collectors.groupingBy 分組\n        Map<Integer, Long> byParity = nums.stream()\n            .collect(Collectors.groupingBy(x -> x % 2, Collectors.counting()));\n        System.out.println(\"by parity: \" + byParity);\n\n        // 4) sorted + distinct + limit\n        List<Integer> top3 = nums.stream().distinct().sorted(Comparator.reverseOrder())\n            .limit(3).collect(Collectors.toList());\n        System.out.println(\"top3 distinct: \" + top3);\n\n        // 5) IntStream.range\n        int fact = IntStream.rangeClosed(1, 5).reduce(1, (a, b) -> a * b);\n        System.out.println(\"5! = \" + fact);\n\n        // 6) joining 字串拼接\n        String csv = nums.stream().map(String::valueOf).collect(Collectors.joining(\",\"));\n        System.out.println(\"csv: \" + csv);\n    }\n}`
