java:`import java.util.*;\npublic class Main {\n    static Optional<Integer> firstEven(List<Integer> xs){\n        for(int x : xs) if(x % 2 == 0) return Optional.of(x);\n        return Optional.empty();\n    }\n\n    public static void main(String[] args){\n        // 1) 取代 null 的設計\n        Optional<String> name = Optional.of(\"Alice\");\n        Optional<String> empty = Optional.empty();\n        System.out.println(name.isPresent() + \" \" + empty.isPresent());\n\n        // 2) ifPresent\n        name.ifPresent(n -> System.out.println(\"hello \" + n));\n        empty.ifPresent(n -> System.out.println(\"never printed\"));\n\n        // 3) orElse / orElseGet\n        String n1 = empty.orElse(\"default\");\n        String n2 = empty.orElseGet(() -> \"computed default\");\n        System.out.println(n1 + \" / \" + n2);\n\n        // 4) map / flatMap\n        Optional<Integer> len = name.map(String::length);\n        System.out.println(\"len=\" + len.orElse(-1));\n\n        // 5) 套到實際邏輯\n        List<Integer> xs = Arrays.asList(1, 3, 5, 8, 9);\n        firstEven(xs).ifPresentOrElse(\n            v -> System.out.println(\"first even = \" + v),\n            () -> System.out.println(\"no even\")\n        );\n\n        // 6) try-with-resources (autoclose)\n        try(Scanner sc = new Scanner(System.in)){\n            if(sc.hasNextLine()) System.out.println(\"echo: \" + sc.nextLine());\n        }\n\n        // 7) try / catch / finally\n        try {\n            int x = Integer.parseInt(\"not a number\");\n            System.out.println(x);\n        } catch(NumberFormatException e){\n            System.out.println(\"caught: \" + e.getMessage());\n        } finally {\n            System.out.println(\"cleanup\");\n        }\n    }\n}`,
java_stdin:`hello from stdin\n`
