java:`import java.util.concurrent.atomic.*;\nimport java.util.concurrent.locks.*;\nimport java.util.concurrent.*;\npublic class Main {\n    static AtomicInteger atomicCnt = new AtomicInteger(0);\n    static int reentrantCnt = 0;\n    static final ReentrantLock lock = new ReentrantLock();\n\n    static void incAtomic(){\n        for(int i=0;i<100000;i++) atomicCnt.incrementAndGet();\n    }\n    static void incReentrant(){\n        for(int i=0;i<100000;i++){\n            lock.lock();\n            try { reentrantCnt++; } finally { lock.unlock(); }\n        }\n    }\n\n    public static void main(String[] args) throws Exception {\n        // 1) AtomicInteger 無鎖原子操作\n        Thread[] ts = new Thread[4];\n        for(int i=0;i<4;i++) ts[i] = new Thread(Main::incAtomic);\n        for(Thread t : ts) t.start();\n        for(Thread t : ts) t.join();\n        System.out.println(\"atomic: \" + atomicCnt.get());\n\n        // 2) ReentrantLock (可重入，比 synchronized 彈性)\n        ts = new Thread[4];\n        for(int i=0;i<4;i++) ts[i] = new Thread(Main::incReentrant);\n        for(Thread t : ts) t.start();\n        for(Thread t : ts) t.join();\n        System.out.println(\"reentrant: \" + reentrantCnt);\n\n        // 3) ExecutorService 執行緒池\n        ExecutorService pool = Executors.newFixedThreadPool(4);\n        Future<Long> fut = pool.submit(() -> {\n            long s = 0;\n            for(int i=1;i<=1000000;i++) s += i;\n            return s;\n        });\n        System.out.println(\"sum 1..1e6 = \" + fut.get());\n        pool.shutdown();\n\n        // 4) CompletableFuture\n        CompletableFuture<String> cf = CompletableFuture\n            .supplyAsync(() -> \"hello\")\n            .thenApply(s -> s + \" world\");\n        System.out.println(cf.get());\n    }\n}`
